#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
"""Observed node-internal links of a stored FISH graph against the source-verified truth table.
  python3 truth_check.py <session_id> [--truth notes/state_links_truth_2026-10-05.tsv] [--scope __main__]
For every row of the table (node, deposit topic, reader entity, verdict REAL / FALSE) find the graph edge deposit F ->
reader F and report its nature: observed (state / join with evidence), candidate (structural, no evidence), polled,
absent. Precision = REAL among observed must be 1.0 (an observed FALSE link is a defect); recall = REAL links observed."""
import argparse, collections, csv, os, sys
import psycopg2
DSN = 'host=localhost port=5432 dbname=fish user=fish password=fish'
ap = argparse.ArgumentParser(); ap.add_argument('session'); ap.add_argument('--truth', default=os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'notes', 'state_links_truth_2026-10-05.tsv'))
ap.add_argument('--scope', default='__main__'); a = ap.parse_args()
con = psycopg2.connect(DSN); cur = con.cursor()
cur.execute("SELECT node_id, type, label, children, attrs, full_name, etype FROM graph_nodes WHERE session_id=%s AND scope=%s", (a.session, a.scope))
N = {}; parent = {}
for nid, typ, label, children, attrs, full, etype in cur.fetchall():
    N[nid] = dict(id=nid, type=typ, label=label or '', attrs=attrs or {}, full=full, etype=etype)
    for ch in children or []: parent[ch] = nid
def anc(x, typ):
    while x in parent:
        x = parent[x]
        if N[x]['type'] == typ: return N[x]
    return None
F = {}
for f in N.values():
    if f['type'] != 'F': continue
    e, n = anc(f['id'], 'E'), anc(f['id'], 'N')
    F[f['id']] = dict(node=(n or {}).get('full') or (n or {}).get('label') or '?', etype=(e or {}).get('etype') or '', ent=(e or {}).get('label') or f['label'])
cur.execute("SELECT source, target, attrs FROM graph_edges WHERE session_id=%s AND scope=%s AND rel='comm' AND level='L3'", (a.session, a.scope))
E = {}
for s_, t_, at in cur.fetchall():
    if s_ in F and t_ in F: E[(s_, t_)] = at or {}
by_node = collections.defaultdict(list)
for fid, f in F.items(): by_node[f['node'].rsplit('/', 1)[-1]].append(fid)
rows = list(csv.DictReader(open(a.truth), delimiter='\t'))
res = collections.Counter(); detail = []
for r in rows:
    node = r['node'].rsplit('/', 1)[-1]; dep_topic = r['deposit_topic']; rtype = r['reader_etype']; rent = r['reader_ent']
    cands = by_node.get(node, [])
    dep = [f for f in cands if F[f]['etype'] == 'sub' and F[f]['ent'].endswith(dep_topic)]
    rd = [f for f in cands if F[f]['etype'] == rtype and (rent in F[f]['ent'] or F[f]['ent'].endswith(rent))]
    status = 'absent'; nat = ''
    for d_ in dep:
        for r_ in rd:
            at = E.get((d_, r_))
            if at is None: continue
            nat = at.get('nature', '')
            if at.get('evidence') or (nat in ('state', 'join') and at.get('polled')): status = 'observed:' + str(at.get('evidence') or 'polled')
            elif nat.endswith('_candidate'): status = status if status.startswith('observed') else 'candidate'
            elif nat in ('state', 'join'): status = status if status.startswith('observed') else 'structural'
    res[(r['verdict'], status.split(':')[0])] += 1
    detail.append((r['link'], r['verdict'], r['pattern'], status, node, dep_topic.rsplit('/', 1)[-1], f"{rtype}:{rent.rsplit('/', 1)[-1]}"))
print(f"{a.session}: {len(rows)} truth-table links")
for k, n in sorted(res.items()): print(f"  verdict {k[0]:5s} -> {k[1]:10s} {n}")
obs_real = res[('REAL', 'observed')]; obs_false = res[('FALSE', 'observed')]; n_real = sum(n for (v, _), n in res.items() if v == 'REAL')
print(f"precision of observed links: {obs_real}/{obs_real + obs_false} = {obs_real / max(1, obs_real + obs_false):.2f}   recall of REAL links: {obs_real}/{n_real} = {obs_real / max(1, n_real):.2f}")
print('\nper link:')
for d in sorted(detail, key=lambda x: (x[1], x[3])):
    print(f"  #{d[0]:>2} {d[1]:5s} {d[2]:6s} {d[3]:30s} {d[4][:28]:28s} {d[5][:28]:28s} -> {d[6][:30]}")
